import base64

ciphertext = base64.b64decode('O1IKUjtbC0A4VkROOVEQVSpfVEUuUBhYZgpAEnoIWU8kRxwcOVwNQD9WWVYuVhJNMg==')
crib = b'passphrase='

# Try different key lengths
for key_len in range(1, 12):
    # Assume key repeats, try to find it
    key_candidate = bytes([ciphertext[i] ^ crib[i] for i in range(min(len(crib), key_len))])

    # Decrypt full message with this key
    def xor_decrypt(data, key):
        return bytes([data[i] ^ key[i % len(key)] for i in range(len(data))])

    plaintext = xor_decrypt(ciphertext, key_candidate)

    # Check if printable
    try:
        decoded = plaintext.decode('ascii')
        if ';' in decoded:
            print(f'Key len {key_len}: {repr(key_candidate)} -> {repr(decoded)}')
    except:
        pass

# Also try with key being the first bytes only
print('\\nTrying 4-byte key pattern:')
for k4 in ['K3y!', 'key!', 'KEY!', 'Key!']:
    key = k4.encode()
    def xor_decrypt(data, key):
        return bytes([data[i] ^ key[i % len(key)] for i in range(len(data))])
    plaintext = xor_decrypt(ciphertext, key)
    try:
        decoded = plaintext.decode('ascii')
        print(f'{k4}: {repr(decoded)}')
    except:
        print(f'{k4}: {repr(plaintext)}')
