    print("max=%d" % max(nums))


def main():
    if len(sys.argv) != 3:
        print("usage: calc.py <cmd> <file>")
        sys.exit(2)
    cmd = sys.argv[1]
    path = sys.argv[2]
    if cmd == "sum":
        cmd_sum(path)
    elif cmd == "count":
        cmd_count(path)
    elif cmd == "max":
        cmd_max(path)
    else:
        print("unknown command: %s" % cmd)
